using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class DragBenchmark305 {
 static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}static T F<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}static void Mouse(PreviewPanel p,string n,Point at){C(p,n,new MouseEventArgs(MouseButtons.Left,1,at.X,at.Y,0));}
 [STAThread]static void Main(string[] a){Directory.CreateDirectory(a[0]);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new MainForm(Path.Combine(a[0],"prefs.xml"))){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();var s=LabelSettings.Default();s.Width=100;s.Height=80;for(int i=1;i<45;i++)s.Texts.Add(new TextItem{Text="Produkt "+i,X=i%8*10,Y=40+i/8*6,Width=10,Height=5});C(f,"Apply",s);var p=F<PreviewPanel>(f,"preview");p.SelectElement(-1);var r=p.ElementRectangle(-1);var start=new Point((int)(r.X+r.Width*.4),(int)(r.Y+r.Height*.4));int edits=0,titles=0;p.ElementEdited+=delegate{edits++;};f.TextChanged+=delegate{titles++;};Mouse(p,"OnMouseDown",start);var watch=Stopwatch.StartNew();Point end=start;for(int i=0;i<2000;i++){end=new Point(start.X+i%80,start.Y+i%40);Mouse(p,"OnMouseMove",end);}Mouse(p,"OnMouseUp",end);watch.Stop();File.WriteAllText(Path.Combine(a[0],"timing.txt"),"2000 mouse messages with 45 text fields: "+watch.Elapsed.TotalMilliseconds+" ms; edits="+edits+"; title changes="+titles);C(f,"Apply",LabelSettings.Default());f.Close();}}catch(Exception e){File.WriteAllText(Path.Combine(a[0],"failed.txt"),e.ToString());Environment.ExitCode=1;}}
}
